{
  "name": "@aundal/ill-be-back",
  "version": "1.0.5",
  "description": "OpenCode plugin that keeps the active session cache warm while you are away.",
  "license": "MIT",
  "type": "module",
  "main": "./src/server.ts",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/aundal/opencode-ill-be-back.git"
  },
  "homepage": "https://github.com/aundal/opencode-ill-be-back#readme",
  "bugs": {
    "url": "https://github.com/aundal/opencode-ill-be-back/issues"
  },
  "exports": {
    ".": "./src/ill-be-back.ts",
    "./server": "./src/ill-be-back.ts",
    "./tui": "./src/ill-be-back.tsx"
  },
  "files": [
    "src",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "prompt-cache"
  ],
  "dependencies": {
    "@opentui/solid": "0.4.0",
    "solid-js": "1.9.12"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.4.0"
  },
  "engines": {
    "opencode": ">=1.4.0"
  }
}
